<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $csrf = App\Core\Security::csrfToken(); ?>
<section><div class="section-heading"><div><p class="eyebrow">Chave administrativa</p><h1>Mata-mata</h1><p><?= $e($phase['championship_name']) ?></p></div></div>
<?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?>
<?php foreach ($bracket as $stage => $ties): ?><article class="panel"><h2><?= $e($stage) ?></h2><table><thead><tr><th>Confronto</th><th>Status</th><th>Partida</th><th>Vencedor</th><th>Decisao</th></tr></thead><tbody><?php foreach ($ties as $tie): ?><tr><td><?= $e($tie['home_team_name'] ?: $tie['home_source']) ?> x <?= $e($tie['away_team_name'] ?: $tie['away_source']) ?></td><td><?= $e($tie['status']) ?></td><td><?php if ($tie['match_id']): ?><a href="<?= $e(App\Core\Config::url('/admin/partidas/' . $tie['match_id'])) ?>">Abrir</a><?php if (($tie['match_status'] ?? '') === 'homologated' && $tie['status'] !== 'finished'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/mata-mata/partidas/' . $tie['match_id'] . '/avancar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Avancar vencedor</button></form><?php endif; ?><?php else: ?>Aguardando vencedores<?php endif; ?></td><td><?= $e($tie['winner_team_name'] ?: '-') ?></td><td><?= $e($tie['decided_by'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></article><?php endforeach; ?>
<?php if ($result): ?><article class="panel"><h2>Resultado final</h2><p>Campeao: <?= $e($result['champion_name']) ?></p><p>Vice: <?= $e($result['runner_up_name']) ?></p></article><?php endif; ?></section>
